    assert_eq!(body["members"][0]["total"]["incomplete"], true);
    assert_eq!(body["individuals"][0]["total"]["amount"], "0");
    assert_eq!(
        body["companies"][0]["id"],
        "10000000-0000-0000-0000-000000000004"
    );
    assert_eq!(
        body["companies"][1]["id"],
        "10000000-0000-0000-0000-000000000007"
    );
    assert_eq!(
        body["companies"][2]["id"],
        "10000000-0000-0000-0000-000000000001"
    );
