p=Path('frontend/tests/rankings.spec.ts'); s=p.read_text().replace('import { rankingFixture }','import { completeRankingFixture, rankingFixture }'); s+='''

for (const [category, label, name] of [
  ["members", "MPs", "Member"],
  ["individuals", "Individuals", "Individual"],
  ["companies", "Companies", "Company"],
  ["parties", "Parties", "Party"],
]) {
  test(`${label} reveal the complete ordered snapshot with stable rows and final keyboard focus`, async ({ page, backend }) => {
    let reads = 0;
    await backend.route("**/api/rankings?*", async (route) => {
      reads += 1;
      await route.fulfill({ json: completeRankingFixture() });
    });
    const requests: string[] = [];
    page.on("request", (request) => requests.push(request.url()));
    await page.goto(`/rankings?category=${category}`);
    const list = page.getByRole("list", { name: `${label} rankings` });
    const items = list.getByRole("listitem");
    const more = page.getByRole("button", { name: "Show more", exact: true });
    await expect(items).toHaveCount(10);
    const first = await items.first().elementHandle();
    const width = await items.first().locator(".ranking-bar").getAttribute("style");
    const before = reads;
    const requestCount = requests.length;
    await more.focus();
    await page.keyboard.press("Enter");
    await expect(items).toHaveCount(20);
    await expect(more).toBeFocused();
    expect(await first?.evaluate((element) => element === document.querySelector(".ranking-list li"))).toBe(true);
    await expect(items.first().locator(".ranking-bar")).toHaveAttribute("style", width ?? "");
    await page.keyboard.press("Enter");
    await expect(items).toHaveCount(23);
    await expect(more).toHaveCount(0);
    await expect(page.getByRole("region", { name: `${label} rankings`, exact: true })).toBeFocused();
    for (let index = 0; index < 23; index += 1) {
      await expect(items.nth(index)).toContainText(`${name} ${index + 1}`);
      await expect(items.nth(index).locator(".rank")).toHaveText(String(index + 1));
    }
    expect(reads).toBe(before);
    expect(requests.length).toBe(requestCount);
    if (category === "parties") await expect(list.getByRole("link")).toHaveCount(0);
  });
}

for (const count of [0, 7, 10, 20]) {
  test(`rankings exhaust correctly with ${count} entries`, async ({ page, backend }) => {
    await backend.route("**/api/rankings?*", async (route) => route.fulfill({ json: completeRankingFixture(count) }));
    await page.goto("/rankings");
    const items = page.getByRole("list", { name: "MPs rankings" }).getByRole("listitem");
    await expect(items).toHaveCount(Math.min(10, count));
    const more = page.getByRole("button", { name: "Show more" });
    if (count > 10) {
      await more.click();
      await expect(items).toHaveCount(count);
    }
    await expect(more).toHaveCount(0);
  });
}

test("revealed prefixes reset on committed category, history, period and refreshed snapshots", async ({ page, backend }) => {
  await backend.route("**/api/rankings?*", async (route) => route.fulfill({ json: { ...completeRankingFixture(), period: new URL(route.request().url()).searchParams.get("period") } }));
  await page.goto("/rankings");
  const items = page.getByRole("listitem");
  const more = page.getByRole("button", { name: "Show more" });
  await more.click();
  await expect(items).toHaveCount(20);
  await page.getByRole("link", { name: "Companies", exact: true }).click();
  await expect(page).toHaveURL(/category=companies/);
  await expect(items).toHaveCount(10);
  await page.goBack();
  await expect(page).not.toHaveURL(/category=companies/);
  await expect(items).toHaveCount(10);
  await more.click();
  await page.goForward();
  await expect(page).toHaveURL(/category=companies/);
  await expect(items).toHaveCount(10);
  await more.click();
  await page.getByRole("combobox", { name: "Reporting period" }).selectOption("historical");
  await expect(page).toHaveURL(/period=historical/);
  await expect(items).toHaveCount(10);
  await more.click();
  await page.reload();
  await expect(items).toHaveCount(10);
});

test("pending period navigation keeps the committed prefix and disables reveal", async ({ page, backend }) => {
  const delayed = Promise.withResolvers<void>();
  await backend.route("**/api/rankings?*", async (route) => {
    const period = new URL(route.request().url()).searchParams.get("period");
    if (period === "historical") await delayed.promise;
    await route.fulfill({ json: { ...completeRankingFixture(), period } });
  });
  await page.goto("/rankings");
  const more = page.getByRole("button", { name: "Show more" });
  await more.click();
  await page.getByRole("combobox", { name: "Reporting period" }).selectOption("historical");
  try {
    await expect(more).toBeDisabled();
    await expect(page.getByRole("listitem")).toHaveCount(20);
  } finally {
    delayed.resolve();
  }
  await expect(page).toHaveURL(/period=historical/);
  await expect(page.getByRole("listitem")).toHaveCount(10);
});
